    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C21","C22"]
    }
  ],
  "evidence_gaps": [
    "No direct scopoletin-specific oral bioavailability or pharmacokinetic record is available; prediction relies on transfer from related polyphenolic natural products.",
    "Scopoletin's smaller size, single phenol, and better solubility than chrysin/curcumin/anthocyanins could raise F, but the magnitude is unknown.",
    "First-pass glucuronidation/sulfation of the 7-OH and coumarin ring metabolism are inferred, not directly measured for scopoletin.",
    "No dose-, species-, or formulation-matched comparison for scopoletin is present."
  ],
  "decision_summary": "The consistent low oral bioavailability of structurally related phenolic natural products (chrysin, curcumin, anthocyanins, flavonolignans, acacetin) and the below-threshold 13.2% value for 7,8-benzoflavone support F < 20% for scopoletin; the favorable physicochemical prior is insufficient to overturn this transferable empirical low-F evidence."
}

